import { inject } from '@angular/core';
import { ActivatedRouteSnapshot, Router, UrlTree } from '@angular/router';
import { getRoutePath, loginRoutePath } from '../app.routes';
import { UserService } from '../common/user/user.service';

export async function canActivateResetPassword(
  route: ActivatedRouteSnapshot
): Promise<boolean | UrlTree> {
  const router = inject(Router);
  const userService = inject(UserService);

  // Check if user is authenticated (they should be after clicking the reset link)
  const user = await userService.getUser();
  
  if (!user) {
    // If no user, redirect to login
    return router.createUrlTree([getRoutePath(loginRoutePath)]);
  }

  // Check if this is a password recovery session by looking for recovery tokens in URL
  if (route.fragment) {
    const params = new URLSearchParams(route.fragment);
    const type = params.get('type');
    
    // Allow access if this is a recovery type or if user is already authenticated
    if (type === 'recovery' || user) {
      return true;
    }
  }

  // If user is authenticated but no recovery type, still allow access
  // (they might have refreshed the page after successful auth)
  return true;
} 